'use strict';
const cameraWorld={w:1100,h:720,min:1,max:2.4};
const cameraClamp=(n,a,b)=>Math.min(b,Math.max(a,n));
const cameraBox=()=>{const b=scene.getBoundingClientRect(),r=b.width>0&&b.height>0?b.width/b.height:1100/720;const w=Math.max(cameraWorld.w,cameraWorld.h*r)/zoom;return {w,h:w/r};};
function cameraLimit(){const {w,h}=cameraBox();cx=w>=1100?550:cameraClamp(cx,w/2,1100-w/2);cy=h>=720?360:cameraClamp(cy,h/2,720-h/2);return {x:cx-w/2,y:cy-h/2,w,h};}
