const cameraStyle=document.createElement('style');cameraStyle.textContent=`#scene{touch-action:none;cursor:grab}#scene.camera-drag{cursor:grabbing}#scene:focus-visible,#cameraMap:focus-visible{outline:2px solid #c5b4ff;outline-offset:-3px}#scene.camera-floor-enter{animation:camera-floor-in .32s ease-out}@keyframes camera-floor-in{from{opacity:.25;transform:translateY(7px)}to{opacity:1;transform:none}}.camera-map-card{margin-top:14px;padding:12px;border:1px solid #343b50;border-radius:12px;background:#101722}.camera-map-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}.camera-map-head strong{font-size:12px}.camera-map-head small{font-size:10px}#cameraMap{aspect-ratio:1100/720;touch-action:manipulation;border:1px solid #36445b;border-radius:8px;background:#0b111b;cursor:crosshair}#cameraMap rect,#cameraMap circle,#cameraMap polygon,#cameraMap text{pointer-events:none}.camera-map-hint{font-size:11px;margin-top:7px}.camera-help{max-width:340px;font-size:11px;color:#a2aec1}.camera-mode{color:#c5b4ff;font-size:11px;letter-spacing:.06em} @media(prefers-reduced-motion:reduce){#scene.camera-floor-enter{animation:none}}`;
document.head.append(cameraStyle);
const cameraMapCard=document.createElement('section');cameraMapCard.className='camera-map-card';cameraMapCard.innerHTML='<div class="camera-map-head"><strong>Mini harita</strong><small id="cameraMode" class="camera-mode">SERBEST</small></div><svg id="cameraMap" viewBox="0 0 1100 720" tabindex="0" role="group" aria-label="Mini harita, tıklayarak veya ok tuşlarıyla kamerayı kaydır"><g id="cameraMapPlan"></g><g id="cameraMapActors"></g><rect id="cameraMapViewport" fill="#b6a6ff18" stroke="#d4c8ff" stroke-width="7" rx="12"/></svg><p class="camera-map-hint" id="cameraMapHint">Alan seç · görüş penceresini kaydır</p>';
$('rooms').after(cameraMapCard);const cameraMap=$('cameraMap');scene.tabIndex=0;scene.setAttribute('aria-label','Sanal ofis: sürükle, yakınlaştır veya ok tuşlarıyla dolaş');
const cameraHelp=scene.parentElement.nextElementSibling.querySelector('small');cameraHelp.className='camera-help';cameraHelp.textContent='Sürükle · tekerlek / iki parmak · ok tuşları · + / − · Home';
let cameraLastFloor=0,cameraLastMap='';
function cameraMini(v){if(cameraLastFloor!==floor){cameraLastFloor=floor;const roomRects=[[12,12,235,210,'#80735e'],[285,12,242,210,'#607c90'],[12,260,235,207,'#526e85'],[285,260,242,207,'#6c6587']];const plan=rect(0,0,540,480,0,'#27394d','#708398')+(floor===1?roomRects.map(r=>rect(r[0],r[1],r[2],r[3],0,r[4],'#9caac0')).join(''):rect(20,20,500,440,0,'#405165','#8294a9'));$('cameraMapPlan').innerHTML=plan;cameraLastMap=null;}
 const dots=floor===1?cast.map(a=>{const s=motionActors[a.id],[x,y]=P(s.x,s.y);return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${a.id===chosen?18:13}" fill="${a.id===chosen?'#f2d4a5':'#b9dded'}" stroke="#111827" stroke-width="4"/>`;}).join(''):'';if(dots!==cameraLastMap){$('cameraMapActors').innerHTML=dots;cameraLastMap=dots;}
 const x=Math.max(0,v.x),y=Math.max(0,v.y),w=Math.min(1100,v.x+v.w)-x,h=Math.min(720,v.y+v.h)-y;const r=$('cameraMapViewport');for(const [k,n] of Object.entries({x,y,width:w,height:h}))r.setAttribute(k,n);$('cameraMode').textContent=motionFollow?'TAKİP':'SERBEST';$('cameraMapHint').textContent=floor===1?'4 dekoratif rol · görüş alanı':'Pasif genişleme katı · ajan yok';}
camera=function(){const v=cameraLimit();scene.setAttribute('viewBox',[v.x,v.y,v.w,v.h].join(' '));$('reset').textContent=Math.round(zoom*100)+'%';cameraMini(v);};
function cameraManual(){motionFollow=false;motionStatus();$('cameraMode').textContent='SERBEST';}
function cameraZoomAt(target,x,y){const old=cameraPoint(scene,x,y);if(!old)return;cameraManual();zoom=cameraClamp(target,cameraWorld.min,cameraWorld.max);const b=scene.getBoundingClientRect(),v=cameraBox();cx=old.x-( (x-b.left)/b.width-.5)*v.w;cy=old.y-((y-b.top)/b.height-.5)*v.h;camera();}
function cameraPan(dx,dy){cameraManual();const b=scene.getBoundingClientRect(),v=cameraBox();if(!b.width||!b.height)return;cx-=dx*v.w/b.width;cy-=dy*v.h/b.height;camera();}
const cameraPointers=new Map();let cameraDragged=false,cameraSuppressUntil=0;
const cameraDistance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);const cameraMid=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});
scene.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;if(!cameraPointers.size){cameraDragged=false;cameraSuppressUntil=0;}if(cameraPointers.size>=2)return;cameraPointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY});if(cameraPointers.size===2){cameraDragged=true;cameraManual();scene.classList.add('camera-drag');for(const id of cameraPointers.keys())try{scene.setPointerCapture(id)}catch{}}});
scene.addEventListener('pointermove',e=>{const prev=cameraPointers.get(e.pointerId);if(!prev)return;const next={...prev,x:e.clientX,y:e.clientY};if(cameraPointers.size===2){const other=[...cameraPointers.entries()].find(([id])=>id!==e.pointerId)[1],before=cameraDistance(prev,other),after=cameraDistance(next,other),m0=cameraMid(prev,other),m1=cameraMid(next,other);if(before>4&&after>4){cameraZoomAt(zoom*after/before,m0.x,m0.y);cameraPan(m1.x-m0.x,m1.y-m0.y);}cameraPointers.set(e.pointerId,next);e.preventDefault();return;}
 if(!cameraDragged&&Math.hypot(next.x-prev.startX,next.y-prev.startY)>=5){cameraDragged=true;scene.classList.add('camera-drag');try{scene.setPointerCapture(e.pointerId)}catch{}cameraPan(next.x-prev.startX,next.y-prev.startY);}else if(cameraDragged)cameraPan(next.x-prev.x,next.y-prev.y);cameraPointers.set(e.pointerId,next);if(cameraDragged)e.preventDefault();});
function cameraPointerEnd(e){if(!cameraPointers.has(e.pointerId))return;cameraPointers.delete(e.pointerId);if(cameraDragged)cameraSuppressUntil=performance.now()+400;if(cameraPointers.size===1){const p=[...cameraPointers.values()][0];p.startX=p.x;p.startY=p.y;}if(!cameraPointers.size){scene.classList.remove('camera-drag');cameraDragged=false;}if(scene.hasPointerCapture(e.pointerId))try{scene.releasePointerCapture(e.pointerId)}catch{}}
for(const event of ['pointerup','pointercancel','lostpointercapture'])scene.addEventListener(event,cameraPointerEnd);window.addEventListener('pointerup',cameraPointerEnd);window.addEventListener('blur',()=>{cameraPointers.clear();cameraDragged=false;scene.classList.remove('camera-drag');});
scene.addEventListener('click',e=>{if(performance.now()<cameraSuppressUntil&&e.detail!==0){e.stopImmediatePropagation();e.preventDefault();cameraSuppressUntil=0;}},true);
scene.addEventListener('wheel',e=>{e.preventDefault();const d=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?scene.clientHeight:1);cameraZoomAt(zoom*Math.exp(-d*.0015),e.clientX,e.clientY);},{passive:false});
function cameraKeys(e){if(e.target!==scene&&e.target!==cameraMap)return;const v=cameraBox(),step=.08;const d={ArrowLeft:[-v.w*step,0],ArrowRight:[v.w*step,0],ArrowUp:[0,-v.h*step],ArrowDown:[0,v.h*step]}[e.key];if(d){e.preventDefault();cameraManual();cx+=d[0];cy+=d[1];camera();}else if(['+','=','-','Home'].includes(e.key)){e.preventDefault();cameraManual();if(e.key==='Home')reset();else{zoom=cameraClamp(zoom+(e.key==='-'?-.2:.2),1,2.4);camera();}}}
scene.addEventListener('keydown',cameraKeys);cameraMap.addEventListener('keydown',cameraKeys);cameraMap.addEventListener('click',e=>{const p=cameraPoint(cameraMap,e.clientX,e.clientY);if(!p)return;cameraManual();cx=p.x;cy=p.y;camera();});
const cameraSelectOriginal=changeCharacter;changeCharacter=function(id,p,focusSelector){cameraSelectOriginal(id,p,focusSelector);if(floor===1&&Object.hasOwn(motionActors,id)){const s=motionActors[id];[cx,cy]=P(s.x,s.y,28);zoom=1.75;camera();}};
